  const m = big ? 300 : r.int(1, 5), n = big ? 300 : r.int(1, 5);
  // start from a valid grid, then maybe break one cell
  const seed = r.arr(m + n, 0, big ? 100 : 3);
  const g = Array.from({ length: m }, (_, i) => Array.from({ length: n }, (_, j) => seed[j - i + m - 1]));
  if (r.bool(0.5)) g[r.int(0, m - 1)][r.int(0, n - 1)] = r.int(0, big ? 100 : 3);
  return [g];
}

