function diagonalsConstant(grid: number[][]): boolean {
  const m = grid.length, n = grid[0].length;
  const starts: [number, number][] = [];
  for (let j = 0; j < n; j++) starts.push([0, j]);
  for (let i = 1; i < m; i++) starts.push([i, 0]);
  for (const [si, sj] of starts) {
    for (let i = si, j = sj; i < m && j < n; i++, j++) {
      if (grid[i][j] !== grid[si][sj]) return false;
    }
  }
  return true;
}

