class Solution:
    def diagonalsConstant(self, grid: List[List[int]]) -> bool:
        m, n = len(grid), len(grid[0])
        starts = [(0, j) for j in range(n)] + [(i, 0) for i in range(1, m)]
        for si, sj in starts:
            i, j = si, sj
            while i < m and j < n:
                if grid[i][j] != grid[si][sj]:
                    return False
                i += 1
                j += 1
        return True

